fn solve(cafes: Vec<i8>) -> i8 {
    // Map each value to its last occurrence index
    let mut last_pos = std::collections::HashMap::new();
    for (idx, &cafe) in cafes.iter().enumerate() {
        last_pos.insert(cafe, idx);
    }
    
    // Find the value with the smallest last occurrence index
    let (result, _) = last_pos
        .into_iter()
        .min_by_key(|&(_, pos)| pos)
        .unwrap(); // Safe because cafes is non-empty and last_pos is non-empty
    
    result
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    cafes
        .iter()
        .enumerate()
        .rev() // Search from the end
        .find(|&(_, &c)| c == cafe)
        .map(|(idx, _)| idx)
        .unwrap_or(0) // Default to 0 if not found, but problem guarantees existence
}